            if (index == -1) {
                fieldsNotFound.add(mapping.getFieldName());
                continue;
            }
            fieldOrder[index] = mapping;
        } else if (mapping.getIndex() < fieldOrder.length) {
            fieldOrder[mapping.getIndex()] = mapping;
